#include <bits/stdc++.h>
using namespace std;

vector<int> primes;

void generate_primes() {
    for (int candidate = 2; candidate < 6000; ++candidate) {
        bool prime_flag = true;
        for (int prime : primes) {
            if (prime * prime > candidate) break;
            if (candidate % prime == 0) {
                prime_flag = false;
                break;
            }
        }
        if (prime_flag) {
            primes.push_back(candidate);
        }
    }
}

map<long long, int> factorize(long long number) {
    map<long long, int> factors_map;
    for (int prime : primes) {
        long long p = prime;
        if (p * p > number) break;
        if (number % p == 0) {
            int count = 0;
            while (number % p == 0) {
                number /= p;
                ++count;
            }
            factors_map[p] = count;
        }
    }
    if (number > 1) {
        factors_map[number] = 1;
    }
    return factors_map;
}

vector<long long> generate_factors(long long number) {
    auto prime_factors = factorize(number);
    vector<long long> result_list = {1};
    for (auto &pf : prime_factors) {
        long long prime = pf.first;
        int count = pf.second;
        vector<long long> temp_list;
        for (auto val : result_list) {
            for (int power = 0; power <= count; ++power) {
                long long new_val = val * (long long)pow(prime, power);
                temp_list.push_back(new_val);
            }
        }
        result_list = temp_list;
    }
    return result_list;
}

long long calculate(int n, int m) {
    unordered_map<int, long long> f_dict;
    f_dict[0] = 0;
    f_dict[1] = 1;
    f_dict[2] = 2;
    for (int i = 3; i <= n; ++i) {
        long long val = 2 * f_dict[i - 1];
        auto factors = generate_factors(i);
        for (auto divisor : factors) {
            if (divisor >= 2 && divisor <= i) {
                long long term1 = f_dict[i / divisor];
                long long term2 = f_dict[(i - 1) / divisor];
                val += term1 - term2;
            }
        }
        val %= m;
        f_dict[i] = val;
    }
    return f_dict[n];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    generate_primes();
    int a, b;
    cin >> a >> b;
    cout << calculate(a, b) << "\n";
    return 0;
}

